    while (getline(inputFile, line)) {
        size_t pos = line.find("hello"); // find first occurrence of target word
        while (pos!= string::npos) { // keep finding subsequent occurrences until none left
            count++;
            pos = line.find("hello", pos + 1); // advance search to next position
        }
    }

    // close the input file and print output count
    inputFile.close();
    cout << "Target word appears " << count << " times in input file." << endl;
    return 0;
}
